 1  interface Input {
 2    timezone?: string;
 3  }
 4  
 5  function formatTime(date: Date, timeZone: string): string {
 6    const parts = new Intl.DateTimeFormat("en-US", {
 7      timeZone,
 8      hour: "numeric",
 9      minute: "2-digit",
10      hour12: true,
11    }).formatToParts(date);
12    const hour = parts.find((p) => p.type === "hour")?.value ?? "?";
13    const minute = parts.find((p) => p.type === "minute")?.value ?? "00";
14    const dayPeriod = parts.find((p) => p.type === "dayPeriod")?.value ?? "";
15    return `${hour}:${minute} ${dayPeriod}`.trim();
16  }
17  
18  function timezoneLabel(zone: string): string {
19    const parts = zone.split("/");
20    return parts[parts.length - 1].replace(/_/g, " ");
21  }
22  
23  export default {
24    execute(input: Input) {
25      const timeZone = input.timezone?.trim() || process.env.TZ || "America/Los_Angeles";
26      try {
27        const formatted = formatTime(new Date(), timeZone);
28        return {
29          content: `It\u2019s exactly ${formatted} in ${timezoneLabel(timeZone)}, Boss. Chrono matrix synced.`,
30          isError: false,
31        };
32      } catch {
33        return {
34          content: `Timezone not recognized, Boss. Fallback is ${timezoneLabel(process.env.TZ || "America/Los_Angeles")}. Chrono matrix synced.`,
35          isError: false,
36        };
37      }
38    },
39  };
